add('## Appendix B — surfaces grouped by ownership\n\n### B1. Runtime readings: all 60, including all 24 null owners\n\nA null owner is not automatically a defect: platform/plan metrics and a deliberately retained core financial summary are different from an operational module. The proposed classification below preserves internal accounting while removing optional workflows. Source: '+ref('app/Reckoner/ReckonerRegistry.php','private const MODULE_MAP')+'.');
function suggested(k,v){if(v.module)return [Array.isArray(v.module)?v.module.join(' OR '):v.module,'Declared; audit nested/drill fields too'];if(k.startsWith('platform.'))return ['Platform only','Keep non-tenant scope enforcement'];if(k.startsWith('plan.'))return ['Always-on account/plan','Explicit exemption'];if(k.startsWith('recurring_')||k==='reminders.count')return ['recurring_invoices','Add owner (R06)'];if(k.startsWith('batch_'))return ['batches_expiry','Add owner; inventory capability alone is insufficient'];if(k.startsWith('returns.'))return ['sales_returns','Add owner (R06)'];if(k==='sales.top_customers')return ['customers + applicable sales surface','Add customer ownership; has_parties can include suppliers'];if(k==='finance.expense_ratio')return ['expenses + meaningful revenue denominator','Gate numerator and define zero-denominator behavior'];if(k.startsWith('sales.'))return ['pos OR invoicing OR sales_orders; or explicit revenue-core exemption','Decide operational detail vs core summary; hide irrelevant drill links'];return ['Explicit core financial summary / accounting_workspace','Net profit is legitimate for an expense-only owner; do not gate it on bank/credit by accident'];}
add(table(['Suggested owner / category','Reading','Current module field','Action'],Object.entries(d.readings).map(([k,v])=>{const s=suggested(k,v);return [s[0],k,Array.isArray(v.module)?v.module.join(' OR '):v.module||'NULL',s[1]];}).sort((a,b)=>a[0].localeCompare(b[0]))));
